class Editor {
  private lines: string[] = [];
  getState() { return this.lines; }
  setState(lines: string[]) { this.lines = lines; }
}

class Caretaker {
  private history: string[][] = [];
  save(e: Editor) { this.history.push(e.getState()); }
  restore(e: Editor, i: number) { e.setState(this.history[i]); }
}

// Version A
class EditorV1 {
  private content: string[] = [];
  getState() { return this.content; } // returns direct reference
  setState(s: string[]) { this.content = s; }
}

// Version B
class Snapshot {
  constructor(public readonly lines: string[]) {}
}
class EditorV2 {
  private content: string[] = [];
  createSnapshot() { return new Snapshot(this.content.slice()); }
  restore(s: Snapshot) { this.content = s.lines.slice(); }
}
